<?php
namespace App\Http\Controllers;
use App\Mail\QuoteMail;use App\Models\Customer;use App\Models\Quote;use App\Models\QuoteItem;use App\Models\ServiceSetting;use App\Models\TireProduct;use App\Models\TireSet;use App\Models\Vehicle;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Mail;use Illuminate\Support\Str;use Illuminate\Validation\Rule;use Illuminate\View\View;use Symfony\Component\HttpFoundation\Response;
class QuoteController extends Controller{
 public function index(Request$request):View{$org=$request->user()->organization_id;$suggestions=TireSet::with(['vehicle.customer','storageLocation'])->where('organization_id',$org)->needsReplacement()->whereNotNull('size')->whereHas('vehicle.customer',fn($q)=>$q->whereNotNull('email'))->whereDoesntHave('vehicle',fn($v)=>$v->whereHas('tireSets',fn($t)=>$t->whereRaw('1=0')))->latest()->paginate(30,['*'],'suggestions_page')->withQueryString();$openSources=Quote::where('organization_id',$org)->whereNotNull('source_tire_set_id')->whereIn('status',['draft','sent','viewed','accepted'])->pluck('source_tire_set_id');$sizes=$suggestions->getCollection()->pluck('size')->filter()->unique();$products=TireProduct::where('organization_id',$org)->where('active',true)->where('stock_quantity','>=',4)->whereIn('size',$sizes)->orderByDesc('price_cents')->get()->groupBy(fn($p)=>$p->size.'|'.$p->season);$suggestions->setCollection($suggestions->getCollection()->filter(fn($set)=>!$openSources->contains($set->id)&&$products->has($set->size.'|'.$set->season))->values());return view('quotes.index',['suggestions'=>$suggestions,'matches'=>$products,'quotes'=>Quote::with(['customer','vehicle','items'])->where('organization_id',$org)->latest()->paginate(40,['*'],'history_page')->withQueryString(),'pipeline'=>['opportunities'=>TireSet::where('organization_id',$org)->needsReplacement()->count(),'sent'=>Quote::where('organization_id',$org)->whereIn('status',['sent','viewed'])->sum('total_cents'),'accepted'=>Quote::where('organization_id',$org)->where('status','accepted')->whereMonth('responded_at',now()->month)->sum('total_cents'),'future'=>TireSet::where('organization_id',$org)->whereBetween('minimum_tread_depth',[3,4])->count()]]);}
 public function suggestion(Request$request,TireSet$tireSet):View{$this->owns($request,$tireSet);$tireSet->load(['vehicle.customer','storageLocation']);$options=$this->options($tireSet);abort_if($options->isEmpty(),404,'Ingen lagervarer matcher dette hjulsettet.');return view('quotes.suggestion',compact('tireSet','options'));}
 public function previewSuggestion(Request$request,TireSet$tireSet):Response{$this->owns($request,$tireSet);$data=$this->suggestionData($request);$tireSet->load('vehicle.customer');$selected=$this->selectedOptions($tireSet,$data['product_ids']);$quote=new Quote(['reference'=>'FORHÅNDSVISNING','total_cents'=>$selected->first()->price_cents*4,'message'=>$data['message']??null,'expires_at'=>now()->addDays(14)]);$quote->setRelation('customer',$tireSet->vehicle->customer);$quote->setRelation('vehicle',$tireSet->vehicle);$quote->setRelation('sourceTireSet',$tireSet);$quote->setRelation('organization',\App\Models\Organization::find($request->user()->organization_id));$labels=['Det beste','Bra valg','Godt valg'];$quote->setRelation('items',$selected->values()->map(fn($product,$i)=>new QuoteItem(['description'=>trim("{$product->brand} {$product->model} {$product->size}"),'recommendation_label'=>$labels[$i]??'Godt valg','quantity'=>4,'unit_price_cents'=>$product->price_cents,'line_total_cents'=>$product->price_cents*4])));return response((new QuoteMail($quote,'#'))->render(),200,['Content-Type'=>'text/html; charset=UTF-8','X-DekkPilot-Preview'=>'quote-email','Cache-Control'=>'no-store, private']);}
 public function sendSuggestion(Request$request,TireSet$tireSet):RedirectResponse{$this->owns($request,$tireSet);$data=$request->validate(['product_ids'=>['required','array','between:1,3'],'product_ids.*'=>['integer'],'message'=>['nullable','string','max:2000']]);$available=$this->options($tireSet);$selected=$available->whereIn('id',$data['product_ids'])->values();abort_unless($selected->count()===count(array_unique($data['product_ids'])),422);return $this->createAndSend($request,$tireSet->vehicle->customer,$tireSet->vehicle,$selected,$data['message']??null,$tireSet);}
 public function bulkReview(Request$request):View{$sets=$this->eligibleSets($request->user()->organization_id);return view('quotes.bulk-review',['sets'=>$sets]);}
 public function bulkSend(Request$request):RedirectResponse{$sets=$this->eligibleSets($request->user()->organization_id);$sent=0;foreach($sets as$set){$this->createAndSend($request,$set->vehicle->customer,$set->vehicle,$this->options($set),null,$set);if(Quote::where('source_tire_set_id',$set->id)->whereIn('status',['draft','sent'])->exists())$sent++;}return redirect()->route('quotes')->with('success',$sent.' tilbud ble lagt i e-postkøen.');}
 public function store(Request$request):RedirectResponse{$org=$request->user()->organization_id;$data=$request->validate(['customer_id'=>['required','integer'],'vehicle_id'=>['required','integer'],'tire_product_id'=>['required','integer'],'quantity'=>['required','integer','between:1,12'],'message'=>['nullable','string','max:2000']]);$customer=Customer::where('organization_id',$org)->findOrFail($data['customer_id']);$vehicle=Vehicle::where('organization_id',$org)->where('customer_id',$customer->id)->findOrFail($data['vehicle_id']);$product=TireProduct::where('organization_id',$org)->where('active',true)->findOrFail($data['tire_product_id']);return$this->createAndSend($request,$customer,$vehicle,collect([$product]),$data['message']??null,null,$data['quantity']);}
 public function showPublic(string$token):View{$quote=$this->quoteFromToken($token);if($quote->expires_at->isPast()&&!in_array($quote->status,['accepted','declined'],true))$quote->update(['status'=>'expired']);elseif($quote->status==='sent')$quote->update(['status'=>'viewed','viewed_at'=>now()]);return view('quotes.public',['quote'=>$quote]);}
 public function purchaseTerms(string$token):View{return view('quotes.purchase-terms',['quote'=>$this->quoteFromToken($token)]);}
 public function respond(Request$request,string$token,\App\Services\AcceptedQuoteWorkflow$workflow):RedirectResponse{$data=$request->validate(['decision'=>['required','in:accepted,declined'],'quote_item_id'=>['nullable','integer'],'terms_accepted'=>['exclude_unless:decision,accepted','required','accepted']]);DB::transaction(function()use($token,$data,$request,$workflow){$quote=Quote::with('items')->where('access_token_hash',hash('sha256',$token))->lockForUpdate()->firstOrFail();abort_if($quote->expires_at->isPast(),410);abort_unless(in_array($quote->status,['sent','viewed'],true),409);$updates=['status'=>$data['decision'],'responded_at'=>now(),'response_ip'=>$request->ip()];if($data['decision']==='accepted'){$item=$quote->items->count()>1?$quote->items->firstWhere('id',(int)($data['quote_item_id']??0)):$quote->items->first();abort_unless($item,422,'Velg ett dekkalternativ.');$updates+=['selected_quote_item_id'=>$item->id,'subtotal_cents'=>$item->line_total_cents,'total_cents'=>$item->line_total_cents,'purchase_terms_accepted_at'=>now(),'purchase_terms_version'=>'2026-08-09'];}$quote->update($updates);if($data['decision']==='accepted')$workflow->create($quote->fresh('items'));DB::table('audit_logs')->insert(['organization_id'=>$quote->organization_id,'action'=>'quote.'.$data['decision'],'subject_type'=>Quote::class,'subject_id'=>$quote->id,'ip_address'=>$request->ip(),'metadata'=>json_encode(['selected_quote_item_id'=>$updates['selected_quote_item_id']??null,'purchase_terms_version'=>$updates['purchase_terms_version']??null]),'created_at'=>now()]);});return redirect()->route('quote.public.show',$token);}
 private function createAndSend(Request$request,Customer$customer,Vehicle$vehicle,$products,?string$message,?TireSet$source=null,int$quantity=4):RedirectResponse{if(!$customer->email)return back()->withErrors(['email'=>'Kunden mangler e-postadresse.']);$plain=Str::random(64);$days=ServiceSetting::where('branch_id',$request->user()->branch_id)->value('quote_expiry_days')??14;$labels=['Det beste','Bra valg','Godt valg'];$quote=DB::transaction(function()use($request,$customer,$vehicle,$products,$message,$source,$quantity,$plain,$days,$labels){$recommended=$products->first();$total=$recommended->price_cents*$quantity;$quote=Quote::create(['public_id'=>(string)Str::uuid(),'organization_id'=>$request->user()->organization_id,'branch_id'=>$request->user()->branch_id,'customer_id'=>$customer->id,'vehicle_id'=>$vehicle->id,'source_tire_set_id'=>$source?->id,'created_by'=>$request->user()->id,'reference'=>'T-'.now()->format('ymd').'-'.strtoupper(Str::random(5)),'access_token_hash'=>hash('sha256',$plain),'subtotal_cents'=>$total,'total_cents'=>$total,'message'=>$message,'expires_at'=>now()->addDays($days)]);foreach($products->take(3)as$i=>$product)$quote->items()->create(['tire_product_id'=>$product->id,'description'=>trim("{$product->brand} {$product->model} {$product->size}"),'recommendation_label'=>$labels[$i]??'Godt valg','position'=>$i+1,'quantity'=>$quantity,'unit_price_cents'=>$product->price_cents,'line_total_cents'=>$product->price_cents*$quantity]);return$quote->load(['customer','vehicle','items','sourceTireSet','organization']);});try{app(\App\Services\CommunicationService::class)->queueQuote($quote,$plain);}catch(\Throwable$e){report($e);return back()->withErrors(['email'=>'Forslaget ble lagret, men e-posten kunne ikke legges i kø.']);}$route=$request->boolean('_action_center')?'actions':'quotes';return redirect()->route($route)->with('success','Tilbudet med '.$quote->items->count().' gode alternativer er lagt i e-postkøen.');}
 private function suggestionData(Request$request):array{return$request->validate(['product_ids'=>['required','array','between:1,3'],'product_ids.*'=>['integer'],'message'=>['nullable','string','max:2000']]);}
 private function selectedOptions(TireSet$set,array$ids){$selected=$this->options($set)->whereIn('id',$ids)->values();if($selected->count()!==count(array_unique($ids)))throw \Illuminate\Validation\ValidationException::withMessages(['product_ids'=>'Ett eller flere valgte dekkalternativer er ikke lenger tilgjengelige. Last siden på nytt og velg blant oppdaterte lagervarer.']);return$selected;}
 private function eligibleSets(int$org){$open=Quote::where('organization_id',$org)->whereNotNull('source_tire_set_id')->whereIn('status',['draft','sent','viewed','accepted'])->pluck('source_tire_set_id');return TireSet::with('vehicle.customer')->where('organization_id',$org)->needsReplacement()->whereNotNull('size')->whereHas('vehicle.customer',fn($q)=>$q->whereNotNull('email')->where(fn($customer)=>$customer->whereNull('notes')->orWhere('notes','not like','[DUMMY]%')))->whereNotIn('id',$open)->get()->filter(fn($set)=>$this->options($set)->isNotEmpty())->values();}
 private function options(TireSet$set){$availability=app(\App\Services\InventoryAvailabilityService::class);return TireProduct::where('organization_id',$set->organization_id)->where('active',true)->where('stock_quantity','>=',4)->where('size',$set->size)->where('season',$set->season)->orderByDesc('price_cents')->get()->filter(fn($product)=>$availability->available($product)>=4)->take(3)->values();}
 private function owns(Request$request,TireSet$set):void{abort_unless($set->organization_id===$request->user()->organization_id,404);}
 private function quoteFromToken(string$token):Quote{abort_unless(strlen($token)===64&&ctype_alnum($token),404);return Quote::with(['customer','vehicle','items','sourceTireSet','organization'])->where('access_token_hash',hash('sha256',$token))->firstOrFail();}
}
